-- 45 The Polyglot Inn: switches the language and writes the lines that carry
-- numbers or names. Every word comes from the string table locale/inn.data;
-- the lines with a `text_key` follow the language by themselves, and the
-- rest go through Locale.get, which picks each language's plural and decimal
-- separator. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/45-polyglot-inn.scene"
local CODES = { "en", "fi", "de", "fr", "es", "pl" }
local PRICES = { 4.5, 2.25, 1.0, 3.75 }
local GUESTS = { "Aino", "Jürgen", "Zoë", "Íñigo", "Łucja", "Margaux", "Oskar" }
local BAR_Y = -262.0
local captions = true
local langs, prices = {}, {}
local welcome, rooms_label, orders_label
local lights = {}
local t, auto, auto_t = 0, true, 0
local which = 1
local guest, rooms, minutes = 1, 6, 25
local guest_t, minute_t = 0, 0

local function choose(i)
    which = i
    Locale.set(CODES[i])
end

function init(entity)
    for i = 1, #CODES do
        langs[i] = Entity.find_by_name("Lang" .. i)
        if langs[i] then Text.set(langs[i], Locale.name(CODES[i])) end
    end
    for i = 1, #PRICES do prices[i] = Entity.find_by_name("Price" .. i) end
    welcome = Entity.find_by_name("Welcome")
    rooms_label = Entity.find_by_name("Rooms")
    orders_label = Entity.find_by_name("Orders")
    for i = 1, 2 do lights[i] = Entity.find_by_name("LanternLight" .. i) end
    -- Start in the system's language if the table has it.
    local now = Locale.current()
    for i, c in ipairs(CODES) do if c == now then which = i end end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt

    -- Choosing a language: a key, a click on its name, or every few seconds
    -- until either.
    for i = 1, #CODES do
        if Input.is_key_just_pressed(tostring(i)) then auto = false; choose(i) end
    end
    if Input.is_key_just_pressed("0") then auto = false; Locale.set("") end
    if Input.is_mouse_left_just_pressed() then
        local mx, my = Input.get_mouse_world_position()
        if math.abs(my - BAR_Y) < 24 then
            for i = 1, #CODES do
                if math.abs(mx - (-330 + (i - 1) * 150)) < 70 then auto = false; choose(i) end
            end
        end
    end
    if auto then
        auto_t = auto_t + dt
        if auto_t > 5 then
            auto_t = 0
            choose(which % #CODES + 1)
        end
    end
    local now = Locale.current()
    for i = 1, #CODES do
        if langs[i] then
            if CODES[i] == now then
                Text.set_color(langs[i], 1.0, 0.78, 0.36, 1)
            else
                Text.set_color(langs[i], 0.45, 0.36, 0.27, 1)
            end
        end
    end

    -- Guests arrive and the kitchen counts down: the counts walk through
    -- every plural form there is.
    guest_t = guest_t + dt
    if guest_t > 3 or Input.is_key_just_pressed("Space") then
        guest_t = 0
        guest = guest % #GUESTS + 1
        rooms = rooms - 1
        if rooms < 0 then rooms = 6 end
    end
    minute_t = minute_t + dt
    if minute_t > 1.2 then
        minute_t = 0
        minutes = minutes - 1
        if minutes < 1 then minutes = 25 end
    end

    for i = 1, #PRICES do
        if prices[i] then Text.set(prices[i], Locale.get("inn_price", { p = PRICES[i] })) end
    end
    if welcome then Text.set(welcome, Locale.get("inn_welcome", { name = GUESTS[guest] })) end
    if rooms_label then Text.set(rooms_label, Locale.get("inn_rooms", { n = rooms })) end
    if orders_label then Text.set(orders_label, Locale.get("inn_orders", { n = minutes })) end

    -- Lanterns breathe.
    for i = 1, 2 do
        if lights[i] then Lighting.set_intensity(lights[i], 1.6 + 0.12 * math.sin(t * 3.1 + i * 2) + 0.06 * math.sin(t * 7.7 + i)) end
    end
end
